                                        let IslandResult::Session(item) = result;
                                        let row_id = option_id(&item.id);
                                        let item_option_id = option_id(&item.id);
                                        let selected_class_id = item_option_id.clone();
                                        let selected_aria_id = item_option_id.clone();
                                        let switch_id = item.id.clone();
                                        let switch_title = item.title.clone();
                                        let row_title = item.title.clone();
                                        let row_project = item.project.clone().unwrap_or_default();
                                        let row_cwd = item.cwd.clone();
                                        let row_branch = item.branch.clone().unwrap_or_default();
                                        let row_origin = item.origin.clone().unwrap_or_default();
                                        let row_time = fmt_relative_time(&item.updated_at);
                                        let row_turns = item.turn_count;
                                        let is_focused = item.is_focused;
                                        view! {
                                            <button
                                                id=row_id
                                                class="island-result"
                                                class:island-result--selected=move || {
                                                    selected_option_id() == selected_class_id
                                                }
                                                class:island-result--focused=is_focused
                                                type="button"
                                                role="option"
                                                tabindex="-1"
                                                aria-selected=move || {
                                                    (selected_option_id() == selected_aria_id).to_string()
                                                }
                                                on:click=move |_| {
                                                    daemon.get_value().switch_session(
                                                        switch_id.clone(),
                                                        switch_title.clone(),
                                                    );
                                                    close();
                                                }
                                            >
                                                <span class="island-result__primary">
                                                    <span class="island-result__title">{row_title}</span>
                                                    <Show when=move || is_focused>
                                                        <span class="island-result__focused">"Focused"</span>
                                                    </Show>
                                                </span>
                                                <span class="island-result__meta">
                                                    <span>{row_project}</span>
                                                    <span class="island-result__path">{row_cwd}</span>
                                                    <span>{row_branch}</span>
                                                    <span>{row_origin}</span>
                                                    <span>{row_time}</span>
                                                    <span>{format!("{row_turns} turns")}</span>
                                                </span>
                                            </button>
                                        }
                                    }
                                />
                            </div>
                        </Show>
                    </div>
                </section>
            </Show>
        </section>
    }
}

