    #[derive(Clone, Copy, PartialEq)]
    enum ProjectAction {
        None,
        NewProject,
        ExistingProject,
    }

    let action_mode: RwSignal<ProjectAction> = RwSignal::new(ProjectAction::None);
    // New-project form.
    let new_name: RwSignal<String> = RwSignal::new(String::new());
