                            log::warn!("sessions fetch not ok");
                            break;
                        }
                        Err(err) => {
                            log::warn!("sessions decode error: {err}");
                            break;
                        }
                    },
                    Err(err) => {
                        log::warn!("sessions fetch error: {err}");
                        break;
                    }
