  min-height: var(--ctl-h-sm);
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  font: 500 11px/1 var(--font);
  cursor: pointer;
}

.island-attention__open:hover {
  background: var(--bg-hover);
