.island-results {
  min-height: 0;
  max-height: min(464px, calc(100vh - var(--island-top) - 72px));
  overflow-y: auto;
  padding: 4px 0 0;
  border-radius: var(--radius);
}

.island-group {
  display: flex;
  flex-direction: column;
}

.island-result {
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.island-result:hover,
