  background: var(--bg-hover);
}

.island-result:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-result__primary,
.island-result__meta {
  display: flex;
  align-items: center;
  min-width: 0;
}

.island-result__primary {
  gap: 8px;
}

.island-result__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
  font: 500 13px/1.35 var(--font);
}

.island-result__focused {
  flex: 0 0 auto;
  padding: 2px 5px;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent-bright);
  font: 600 9px/1.3 var(--font);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.island-result__meta {
  gap: 0;
  margin-top: 3px;
  color: var(--fg-3);
  font: 400 10px/1.4 var(--font);
  white-space: nowrap;
  overflow: hidden;
}

.island-result__meta > span {
  min-width: 0;
  max-width: 18ch;
  overflow: hidden;
